# short-circuit is only observable on a socket pair.
t = t.replace('''    'select_buffered': \'\'\'<?php
$h = fopen("php://memory", "w+");
fwrite($h, "hello world\\\\n");
rewind($h);
fgets($h, 6);
$r = [$h]; $w = null; $e = null;
var_dump(stream_select($r, $w, $e, 0));
var_dump(count($r));
\'\'\',''', '''    'select_buffered': \'\'\'<?php
$pair = stream_socket_pair(STREAM_PF_UNIX, STREAM_SOCK_STREAM, 0);
fwrite($pair[1], "hello world\\\\n");
fgets($pair[0], 6);
$r = [$pair[0]]; $w = null; $e = null;
var_dump(stream_select($r, $w, $e, 0));
var_dump(count($r));
\'\'\',''')
p.write_text(t)
print('probe fixed')
